D={
920007:("going to: planos","**Going to** serve para planos já decididos: *I'm going to travel*. Negativa: *I'm not going to stay*.",[("I'm {{going to travel}} by balloon.","Vou viajar de balão."),("{{Are you going to}} come with us?","Você vai conosco?"),("I'm {{not going to}} stay.","Não vou ficar."),("We {{are going to}} see the rainforest.","Vamos ver a floresta tropical.")],"Qual frase mostra um plano?",["I'm going to hike.","I hiked.","I hike."],0,"Be going to + verbo = plano."),
81050:("as … as","Para dizer que são iguais: **as + adjetivo + as**. Para negar: *not as … as*.",[("Tom is {{as tall as}} Leo.","O Tom é tão alto quanto o Leo."),("This train is {{as fast as}} that one.","Este trem é tão rápido quanto aquele."),("It {{doesn't}} cost {{as much as}} that.","Não custa tanto quanto aquilo."),("The giant is {{not as small as}} me.","O gigante não é tão pequeno quanto eu.")],"Complete: “He is ___ strong as me.”",["as","than","more"],0,"A estrutura é as … as."),
80270:("Comparar cores","Comparativo: **-er than**. *Dark → darker, light → lighter, bright → brighter*.",[("I want a {{darker}} shirt.","Quero uma camisa mais escura."),("This shirt is {{darker than}} that one.","Esta camisa é mais escura que aquela."),("That color is {{brighter}}.","Aquela cor é mais viva."),("This shade is {{lighter than}} the blue.","Este tom é mais claro que o azul.")],"Qual é o comparativo de “light”?",["lighter","more light","lightest"],0,"Light é curto: lighter."),
81051:("faster than / not as … as","*Faster than* mostra superioridade; **not as … as** mostra que é menos. Irregular: *better*.",[("The hare is {{faster than}} the turtle.","A lebre é mais rápida que a tartaruga."),("The turtle isn't {{as fast as}} the hare.","A tartaruga não é tão rápida quanto a lebre."),("A plan is {{better than}} speed.","Um plano é melhor que velocidade."),("She is {{stronger than}} me.","Ela é mais forte que eu.")],"“Not as fast as” significa…",["mais rápido","menos rápido","igual"],1,"Not as … as: tem menos da qualidade."),
81052:("some, any, no","**Some** nas frases positivas; **any** nas perguntas e negativas; **no** = nenhum.",[("I have {{some}} carrots.","Tenho algumas cenouras."),("Do you have {{any}} potatoes?","Você tem batatas?"),("We have {{no}} bread.","Não temos pão."),("I don't have {{any}} milk.","Não tenho leite.")],"Complete: “Do you have ___ eggs?”",["some","any","no"],1,"Em perguntas, any."),
81053:("much / many / a lot of","**Many** com contáveis; **much** com incontáveis; **a lot of** serve para os dois.",[("{{How many}} apples do you want?","Quantas maçãs você quer?"),("{{How much}} milk do you need?","De quanto leite você precisa?"),("I eat {{a lot of}} fruit.","Como muita fruta."),("I don't eat {{many}} sweets.","Não como muitos doces.")],"Complete: “How ___ water do you drink?”",["many","much","few"],1,"Água não se conta: how much."),
81054:("a few / a little","**A few** com contáveis; **a little** com incontáveis. Ambos têm sentido positivo: “um pouco”.",[("I need {{a few}} eggs.","Preciso de alguns ovos."),("Add {{a little}} water.","Acrescente um pouco de água."),("We have {{a few}} apples.","Temos algumas maçãs."),("Put in {{a little}} salt.","Ponha um pouco de sal.")],"Complete: “Add ___ flour.”",["a few","a little","many"],1,"Flour (farinha) é incontável: a little."),
81055:("verbo + -ing","Certos verbos pedem outro verbo **com -ing**: *enjoy, finish, keep*. Sem **to**!",[("I {{enjoy running}}.","Gosto de correr."),("She will {{finish cooking}} soon.","Ela vai terminar de cozinhar logo."),("{{Keep going}}!","Continue!"),("We {{enjoy making}} cookies.","Gostamos de fazer biscoitos.")],"Qual está certa?",["I finish to read.","I finish reading.","I finish read."],1,"Depois de finish: verbo com -ing."),
81056:("verbo + to","Estes verbos pedem **to + verbo**: *want to, need to, decide to*.",[("I {{want to travel}}.","Quero viajar."),("I {{need to save}} money.","Preciso economizar."),("She {{decided to go}}.","Ela decidiu ir."),("We {{wish to}} see the well.","Desejamos ver o poço.")],"Qual está certa?",["I want travel.","I want to travel.","I want traveling."],1,"Depois de want: to + verbo."),
920008:("must, should, have to","**Must** é obrigação forte; **should** é conselho; **don't have to** é “não é necessário”.",[("You {{must}} hide carefully.","Você precisa se esconder com cuidado."),("You {{should}} rest tonight.","Você deveria descansar esta noite."),("I {{have to}} follow him now.","Tenho de segui-lo agora."),("You {{don't have to}} come.","Você não precisa vir.")],"Qual é um conselho?",["You must stop.","You should rest.","You have to pay."],1,"Should dá um conselho."),
81057:("Pedidos educados","Para pedir: **I would like** + coisa, **Could you** + verbo, **May I** + verbo. Sempre com *please* e *thank you*.",[("I {{would like}} a coffee, please.","Eu gostaria de um café, por favor."),("{{Could you}} pass the salt?","Você poderia passar o sal?"),("{{May I}} take your order?","Posso anotar seu pedido?"),("{{Of course}}. Here you are.","Claro. Aqui está.")],"Qual pedido é mais educado?",["Give me a coffee.","I would like a coffee, please.","I want coffee."],1,"I would like + please é a forma mais polida."),
81058:("Let's / Shall we","Para sugerir: **Let's** + verbo ou **Shall we** + verbo? Respostas: *Good idea! / Why not? / Sorry, I can't.*",[("{{Let's go}} to the lake.","Vamos ao lago."),("{{Shall we}} take a break?","Vamos fazer uma pausa?"),("{{Good idea}}! Let's skate!","Boa ideia! Vamos patinar!"),("{{Sorry, I can't}}.","Desculpe, não posso.")],"Qual é uma sugestão?",["Shall we eat?","We shall eat.","You eat shall."],0,"Shall we + verbo sugere algo."),
80213:("would rather","Para dizer o que prefere: **I'd rather** + verbo. *I'd = I would*. Para escolher: *tea or coffee?*",[("I'd {{rather have}} tea.","Prefiro tomar chá."),("Would you like tea {{or}} coffee?","Você quer chá ou café?"),("{{No sugar}}, please.","Sem açúcar, por favor."),("I'd {{rather}} stay home.","Prefiro ficar em casa.")],"Complete: “I'd rather ___ tea.”",["to have","have","having"],1,"Depois de would rather, verbo básico."),
81059:("Pronomes possessivos","Substituem o nome da coisa: **mine, yours, his, hers, ours, theirs**.",[("This bag is {{mine}}.","Esta bolsa é minha."),("Is this phone {{yours}}?","Este celular é seu?"),("The blue coat is {{his}}.","O casaco azul é dele."),("The red one is {{hers}}.","O vermelho é dela.")],"Complete: “This is my book. It's ___.”",["me","mine","my"],1,"Mine substitui “my book”."),
81060:("Reflexivos","Quando sujeito e objeto são a mesma pessoa: **myself, yourself, himself, herself, ourselves, themselves**.",[("I did it {{myself}}.","Eu mesmo fiz."),("Do it {{yourself}}!","Faça você mesmo!"),("He built it {{himself}}.","Ele mesmo construiu."),("Help {{yourself}}!","Fique à vontade!")],"Complete: “She cut ___.”",["her","herself","she"],1,"Quem corta e quem é cortado são a mesma pessoa."),
81061:("someone / anyone / nobody","**Someone** em frases positivas; **anyone** em perguntas e negativas; **nobody** = ninguém; **everyone** = todos.",[("{{Someone}} is in the hall.","Alguém está no corredor."),("Is there {{anyone}} here?","Tem alguém aqui?"),("{{Nobody}} knows the answer.","Ninguém sabe a resposta."),("{{Everyone}} loves a mystery.","Todo mundo ama um mistério.")],"Complete: “I don't see ___.”",["someone","anyone","nobody"],1,"Na negativa, anyone."),
81062:("both / either / neither","**Both** = os dois; **either** = qualquer um; **neither** = nenhum dos dois.",[("{{Both}} doors are closed.","As duas portas estão fechadas."),("You can open {{either}} door.","Você pode abrir qualquer porta."),("{{Neither}} door is safe.","Nenhuma das portas é segura."),("{{Both}} of us agree.","Nós dois concordamos.")],"Qual significa “nenhum dos dois”?",["both","either","neither"],2,"Neither = nenhum dos dois."),
81063:("Advérbios de modo","Dizem **como** se faz algo: adjetivo + **-ly** (*slow → slowly*). Irregular: *good → well*.",[("He walks {{slowly}}.","Ele anda devagar."),("Drive {{carefully}}.","Dirija com cuidado."),("She works very {{hard}}.","Ela trabalha muito."),("He speaks English {{well}}.","Ele fala bem inglês.")],"Qual é o advérbio de “good”?",["goodly","well","gooder"],1,"Good é irregular: well."),
920009:("Could you / May I","**Could** e **would** deixam o pedido mais educado que *can*: *Could you open the window?*",[("{{Could you}} open the window?","Você poderia abrir a janela?"),("{{May I}} ask a question?","Posso fazer uma pergunta?"),("{{Would you mind}} waiting a minute?","Você se importaria de esperar um minuto?"),("{{Please}}, take a seat.","Por favor, sente-se.")],"Qual é o mais educado?",["Open the door.","Can you open the door?","Could you open the door?"],2,"Could you é mais polido que can you."),
81064:("through, across, along","Preposições de movimento: **through** (por dentro), **across** (de lado a lado), **along** (ao longo), **over**, **under**.",[("We sail {{through}} the storm.","Navegamos através da tempestade."),("He swims {{across}} the river.","Ele atravessa o rio nadando."),("We walk {{along}} the beach.","Caminhamos ao longo da praia."),("The boat goes {{under}} the bridge.","O barco passa por baixo da ponte.")],"Complete: “She walks ___ the street.” (de um lado a outro)",["across","along","under"],0,"Across = de um lado a outro."),
81065:("make × do","**Make** = criar (*a cake, a bed, a mistake*). **Do** = tarefas (*homework, the dishes*).",[("I {{make}} my bed.","Eu arrumo minha cama."),("I {{do}} my homework.","Faço minha lição de casa."),("The elves {{make}} shoes.","Os elfos fazem sapatos."),("We {{do}} the dishes after dinner.","Lavamos a louça depois do jantar.")],"Qual verbo combina com “homework”?",["make","do","get"],1,"A combinação natural é do homework."),
81066:("Rotina com get","*Get* aparece em muitas expressões da rotina: **get up, get ready, get home, get dressed**.",[("I {{get up}} at seven.","Levanto às sete."),("I {{get ready}} for work.","Fico pronto para o trabalho."),("I {{get home}} at six.","Chego em casa às seis."),("First I {{get dressed}}.","Primeiro, me visto.")],"Como dizer “chego em casa”?",["I get home","I arrive to home","I go to the house"],0,"Get home = chegar em casa."),
81067:("bring × take","**Bring** = trazer (para onde estou). **Take** = levar (para longe). *Bring a dessert to my house. Take this to Tom.*",[("Please {{bring}} a dessert.","Por favor, traga uma sobremesa."),("I'll {{take}} a chocolate cake.","Vou levar um bolo de chocolate."),("{{Bring}} me a piece of cake.","Traga-me um pedaço de bolo."),("{{Take}} this basket to Tom.","Leve esta cesta para o Tom.")],"Complete: “___ this letter to Ana, please.” (levar)",["Bring","Take","Come"],1,"Levar para longe de mim: take."),
81068:("look / see / watch","**Look** = dirigir o olhar (*look at*). **See** = enxergar. **Watch** = observar algo que se move.",[("{{Look at}} the sky!","Olhe para o céu!"),("I can {{see}} the park.","Consigo ver o parque."),("I {{watch}} TV at night.","Assisto TV à noite."),("The neighbor {{watches}} us from the window.","O vizinho nos observa da janela.")],"Qual verbo combina com “TV”?",["look","see","watch"],2,"Watch TV."),
81069:("say / tell / speak / talk","**Say** = dizer palavras. **Tell** = contar a alguém. **Speak** = falar uma língua. **Talk** = conversar.",[("Please {{say}} it again.","Por favor, diga de novo."),("{{Tell}} me the truth.","Conte-me a verdade."),("Do you {{speak}} English?","Você fala inglês?"),("Let's {{talk}} about it.","Vamos conversar sobre isso.")],"Qual verbo combina com “English”?",["tell","speak","say"],1,"Speak English."),
81070:("will × going to","**Going to** = planos já feitos. **Will** = previsão ou decisão na hora.",[("I {{am going to}} see Hamlet.","Vou ver Hamlet (já planejei)."),("I think it {{will}} be long.","Acho que vai ser longo."),("{{Will}} you like it?","Você vai gostar?"),("OK, I'{{ll}} take that one.","Certo, levo aquele.")],"Qual mostra uma decisão na hora?",["I'm going to buy it.","I'll take it!","I bought it."],1,"Decisão no momento: will."),
30041:("Previsão do tempo","Para a previsão: **will** + verbo ou **be going to**. *It will rain tomorrow. It's going to be foggy.*",[("{{What's the forecast}} for tomorrow?","Qual é a previsão para amanhã?"),("It's {{going to be}} foggy in the morning.","Vai ter neblina de manhã."),("Tonight {{will be}} stormy.","Esta noite vai ter tempestade."),("It {{will rain}} on Sunday.","Vai chover no domingo.")],"Como perguntar a previsão?",["What's the forecast?","How is the forecast?","Who is the forecast?"],0,"What's the forecast? pergunta a previsão."),
70082:("Previsão: will / going to","Para previsões: **will** + verbo ou **be going to**. Ambos dizem o que o tempo vai fazer.",[("It {{will be}} overcast.","Vai ficar nublado."),("It's {{going to pour}}.","Vai cair um temporal."),("{{Rain or shine}}, I'm going to work.","Faça chuva ou sol, vou trabalhar."),("Take cover if it {{pours}}!","Abrigue-se se chover forte!")],"Qual frase prevê o tempo?",["It rained.","It's going to rain.","It rains."],1,"Be going to prevê o que vem."),
920010:("Have you ever…?","**Have/has + particípio** fala de experiência, sem dizer quando. *Have you ever seen…?*",[("{{Have you ever}} seen skydiving?","Você já viu paraquedismo?"),("Yes, I {{have}}.","Sim, já vi."),("I {{have never climbed}} a mountain.","Nunca escalei uma montanha."),("She {{has}} tried scuba diving.","Ela já experimentou mergulho.")],"Qual é o particípio de “see”?",["saw","seen","seed"],1,"See, saw, seen."),
81071:("go / come + partícula","*Go* e *come* mudam de sentido com partículas: **come in, come back, go out, go away**.",[("Please {{come in}}.","Por favor, entre."),("When will you {{come back}}?","Quando você volta?"),("Let's {{go out}} tonight.","Vamos sair hoje à noite."),("{{Go away}}, rain!","Vá embora, chuva!")],"“Go out” significa…",["entrar","sair","voltar"],1,"Go out = sair."),
81072:("feel + adjetivo","Sentimentos: **feel + adjetivo** (*I feel happy*) ou **be + adjetivo** (*He is angry*).",[("I {{feel happy}}.","Eu me sinto feliz."),("She {{feels sad}}.","Ela se sente triste."),("He {{is angry}} at me.","Ele está bravo comigo."),("We {{are excited}}!","Estamos animados!")],"Complete: “She ___ scared.”",["feel","feels","feeling"],1,"She pede feels."),
81073:("in / on / under / next to","**In** = dentro; **on** = em cima, tocando; **under** = embaixo; **next to** = ao lado.",[("The lamp is {{on}} the table.","A lâmpada está sobre a mesa."),("The bed is {{under}} the window.","A cama fica embaixo da janela."),("My clothes are {{in}} the closet.","Minhas roupas estão no armário."),("The mirror is {{next to}} the shelf.","O espelho está ao lado da estante.")],"Onde está o gato? “The cat is ___ the box.” (dentro)",["in","on","under"],0,"In = dentro."),
81074:("have to / should","**Have to** = obrigação (*I have to clean*). **Should** = conselho. Com he/she: **has to**.",[("I {{have to}} clean the kitchen.","Preciso limpar a cozinha."),("She {{has to}} do the laundry.","Ela tem de lavar a roupa."),("You {{should}} help your mom.","Você deveria ajudar sua mãe."),("We {{have to}} take out the trash.","Temos de tirar o lixo.")],"Complete: “He ___ do the dishes.”",["have to","has to","should to"],1,"He pede has to."),
81075:("Could you / Would you","Para favores: **Could you…?** ou **Would you…?** + verbo. Respostas: *Sure. / Of course.*",[("{{Could you}} hold the door?","Você poderia segurar a porta?"),("{{Would you}} stop the noise?","Você poderia parar o barulho?"),("{{Can I ask}} a favor?","Posso pedir um favor?"),("{{Sure}}. No problem.","Claro. Sem problema.")],"Complete: “___ you help me, please?”",["Could","Does","Are"],0,"Could you? abre o pedido educado."),
81076:("Presente contínuo","Para ações **agora**: **am/is/are + verbo-ing**. *The plumber is working.* Pergunta: *Is he fixing it?*",[("The plumber {{is working}} now.","O encanador está trabalhando agora."),("We {{are calling}} the plumber.","Estamos chamando o encanador."),("{{Is he using}} a new tool?","Ele está usando uma ferramenta nova?"),("Water {{is leaking}} from the pipe.","A água está vazando do cano.")],"Qual está certa?",["He fix the sink now.","He is fixing the sink now.","He fixing the sink now."],1,"Presente contínuo: is + verbo-ing."),
}
